def populate_full_name(apps, schema_editor):
    User = apps.get_model('accounts', 'User')
    for user in User.objects.all().iterator():
        name = f'{user.first_name} {user.last_name}'.strip()
        if not user.full_name:
            user.full_name = name or user.email
            user.save(update_fields=['full_name'])


def map_consent_types(apps, schema_editor):
    Consent = apps.get_model('accounts', 'ConsentRecord')
    mapping = {
        'TERMS': 'TERMS_OF_SERVICE',
        'PRIVACY': 'PRIVACY_POLICY',
        'HEALTH_DATA': 'HEALTH_DATA_PROCESSING',
    }
    for old, new in mapping.items():
        Consent.objects.filter(document_type=old).update(document_type=new)


